rollback.sql:
DROP PROCEDURE IF EXISTS BT.SP_DETACH_API_REQUEST_PAYLOAD(
    IN INTEGER,
    OUT TEXT, OUT TEXT, OUT TEXT, OUT INTEGER
);

changeSet.sql:
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'quant_app') THEN
        GRANT EXECUTE ON PROCEDURE BT.SP_DETACH_API_REQUEST_PAYLOAD(
            IN INTEGER,
            OUT TEXT, OUT TEXT, OUT TEXT, OUT INTEGER
        ) TO quant_app;
    END IF;
END $$;
